import{_ as a,o,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const s=JSON.parse('{"title":"记忆系统","description":"区分状态、短期记忆、长期记忆和业务数据，并建立记忆读写与治理闭环。","frontmatter":{"title":"记忆系统","description":"区分状态、短期记忆、长期记忆和业务数据，并建立记忆读写与治理闭环。"},"headers":[],"relativePath":"py-agent/knowledge/memory/index.md","filePath":"py-agent/knowledge/memory/index.md","lastUpdated":1785318762000}'),l={name:"py-agent/knowledge/memory/index.md"};function i(n,e,d,m,p,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="记忆系统" tabindex="-1">记忆系统 <a class="header-anchor" href="#记忆系统" aria-label="Permalink to &quot;记忆系统&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>记忆不是“把聊天记录存进数据库”。一个可用记忆系统必须决定什么值得保留、保存多久、谁可以读取、冲突时相信什么，以及错误记忆怎样更新或删除。本分组以 LangGraph Checkpointer 和 Store 映射短期与长期记忆。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成后，你应该能够：</p><ol><li>区分模型上下文、Agent State、Checkpoint、Store、RAG 与业务数据库；</li><li>使用线程 ID 和 Checkpointer 保存、恢复短期运行状态；</li><li>使用命名空间和 Store 保存跨线程事实或偏好；</li><li>设计记忆的抽取、确认、检索、合并、更新和删除；</li><li>处理来源、置信度、冲突、过期、权限和数据主体请求；</li><li>分别评测写入质量、检索质量和对任务的实际影响。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/knowledge/memory/memory-model-boundaries">记忆模型与边界</a>：先建立数据职责和生命周期。</li><li><a href="/py-agent/knowledge/memory/short-term-memory-checkpoints">短期记忆与 Checkpoint</a>：线程内状态与恢复。</li><li><a href="/py-agent/knowledge/memory/long-term-memory-store">长期记忆与 Store</a>：跨线程数据与 API。</li><li><a href="/py-agent/knowledge/memory/memory-write-retrieve-update">记忆写入、检索与更新</a>：完整读写策略。</li><li><a href="/py-agent/knowledge/memory/memory-governance-evaluation">记忆治理与评测</a>：隐私、生命周期和质量闭环。</li></ol><h2 id="_3-核心边界" tabindex="-1">3. 核心边界 <a class="header-anchor" href="#_3-核心边界" aria-label="Permalink to &quot;3. 核心边界&quot;">​</a></h2><p>Checkpointer 保存线程的图状态快照，Store 保存应用定义的跨线程数据；两者都不是订单、账户等业务事实的权威数据库。RAG 检索共享知识，记忆则围绕运行主体保存经过治理的信息。</p>',10)])])}const _=a(l,[["render",i]]);export{s as __pageData,_ as default};
